describe('Mark All Notifications as Read', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should mark all notifications as read with one click', () => {
    // Verify initial state: 5 notifications visible
    cy.get('[data-testid="notification-count"]').should('contain', '5');
    cy.get('[data-testid="notification-item"]').should('have.length', 5);

    // Verify notifications are not marked as read
    cy.get('[data-testid="notification-item"]').eq(0).should('have.class', 'unread');
    cy.get('[data-testid="notification-item"]').eq(1).should('have.class', 'unread');

    // Click the mark all as read button
    cy.get('[data-testid="mark-all-as-read-btn"]').click();

    // Verify all notifications are now marked as read
    cy.get('[data-testid="notification-item"]').each(($el, index, $list) => {
      cy.wrap($el).should('have.class', 'read');
    });

    // Verify notification count is updated
    cy.get('[data-testid="notification-count"]').should('contain', '0');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'All notifications marked as read');
  });

  it('should handle edge case: no notifications available', () => {
    // Verify initial state: 0 notifications visible
    cy.get('[data-testid="notification-count"]').should('contain', '0');

    // Verify success message is not visible when no notifications are available
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Click the mark all as read button
    cy.get('[data-testid="mark-all-as-read-btn"]').click();

    // Verify success message still does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify no notifications are marked as read
    cy.get('[data-testid="notification-item"]').should('not.exist');

    // Verify notification count remains unchanged
    cy.get('[data-testid="notification-count"]').should('contain', '0');
  });
});
